TLM.f("Sancti/11-09cc",{"officium":"S. Theodori Martyris","rule":["vide C2;"],"fallback":"Commune/C2","from":{"Introitus":"Commune/C2","Lectio":"Commune/C2","Graduale":"Commune/C2","GradualeP":"Commune/C2","Tractus":"Commune/C2","Evangelium":"Commune/C2","Offertorium":"Commune/C2","Communio":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus: et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus: et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei."}],"Oratio":[{"k":"text","la":"Deus, qui nos beáti Theodóri Mártyris tui confessióne gloriósa circúmdas et prótegis: præsta nobis ex ejus imitatióne profícere, et oratióne fulcíri."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:10-14"},{"k":"text","la":"Justum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:34-42"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte arbitrári, quia pacem vénerim míttere in terram: non veni pacem míttere, sed gládium. Veni enim separáre hóminem advérsus patrem suum, et fíliam advérsus matrem suam, et nurum advérsus socrum suam: et inimíci hóminis doméstici ejus. Qui amat patrem aut matrem plus quam me, non est me dignus: et qui amat fílium aut fíliam super me, non est me dignus. Et qui non áccipit crucem suam, et séquitur me, non est me dignus. Qui invénit ánimam suam, perdet illam: et qui perdíderit ánimam suam propter me, invéniet eam. Qui récipit vos, me récipit: et qui me récipit, récipit eum, qui me misit. Qui récipit prophétam in nómine prophétæ, mercédem prophétæ accípiet: et qui récipit justum in nómine justi, mercédem justi accípiet. Et quicúmque potum déderit uni ex mínimis istis cálicem aquæ frígidæ tantum in nómine discípuli: amen, dico vobis, non perdet mercédem suam."}],"Offertorium":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum: et constituísti eum super ópera mánuum tuárum, Dómine."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, fidélium preces cum oblatiónibus hostiárum: et, intercedénte beáto Theodóro Mártyre tuo, per hæc piæ devotiónis offícia ad cœléstem glóriam transeámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:24"},{"k":"text","la":"Qui vult veníre post me, ábneget semetípsum, et tollat crucem suam, et sequátur me."}],"Postcommunio":[{"k":"text","la":"Præsta nobis, quǽsumus, Dómine: intercedénte beáto Theodóro Mártyre tuo; ut, quod ore contíngimus, pura mente capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"39bba9d28c693731":{"t":"<i>Pomolimo se</i>.\n[prev. M.B.] Bože koji nas okružuješ i štitiš slavnom ispovijedi vjere tvojeg blaženog mučenika Teodora, daj nam napredovati u njegovom nasljedovanju i ojačati po njegovoj molitvi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → tui","kn":"Bože, koji nas zaštićuješ slavnim mučeništvom blaženog Teodora, mučenika svoga, podaj, da nasljedujući njega napredujemo i da nas štiti njegov zagovor, po G. n. • BI. Gracija 9. XI.","knRef":"Kniewald 1942, str. 772–773 (snimka 387) (OCR)"},"4b98ab9a4411341e":{"t":"Sa žrtvenim prinosima primi, Gospodine, i molitve svojih vjernika da zagovorom tvojeg blaženog mučenika Teodora po ovoj službi pobožne odanosti prijeđemo u nebesku slavu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, prošnje svojih vjernih s prinosom žrtava i zagovorom blaženog Teodora, mučenika svoga, podaj, da po ovoj službi pobožne bogoljubnos'ti prijeđemo u nebesku slavu, po G. h.","knRef":"Kniewald 1942, str. 772–773 (snimka 387) (OCR)"},"034c7cae0a3d674a":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine, po zagovoru svojeg blaženog mučenika Teodora da čistom dušom prihvatimo što smo ustima primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, molimo, Gospodine, da zagovorom Tvojih svetih mučenika I. i I., čistom dušom prihvatimo, što ustima primamo, po G. n.","knRef":"Kniewald 1942, str. 806–807 (snimka 404) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
